use vstd::prelude::*;

verus! {
    // For two non‐empty input vectors seq1 and seq2,
    // construct:
    // 1) A Vec<Vec<i8>> of length seq1.len(), where each sub‐Vec has length 1
    //    and contains the corresponding element of seq1.
    // 2) A Vec<Vec<i8>> of length 1, whose single sub‐Vec is a copy of seq2.
    fn ix_(seq1: Vec<i8>, seq2: Vec<i8>) -> (res1: Vec<Vec<i8>>, res2: Vec<Vec<i8>>)
        requires
            seq1.len() > 0,
            seq2.len() > 0,
        ensures
            // First output has same length as seq1
            res1.len() == seq1.len() &&
            // each row is a singleton equal to the corresponding element
            forall(|i: usize| i < seq1.len() ==>
                res1[i].len() == 1 && res1[i][0] == seq1[i]) &&
            // Second output has exactly one row
            res2.len() == 1 &&
            // that single row is a copy of seq2
            forall(|j: usize| j < seq2.len() ==> res2[0][j] == seq2[j]),
    {
        // Build the first 2D list: one‐element rows from seq1
        let mut r1: Vec<Vec<i8>> = Vec::new();
        let mut i: usize = 0;
        while i < seq1.len()
            invariant i <= seq1.len(),
            invariant r1.len() == i,
            invariant forall(|k: usize| k < i ==>
                r1[k].len() == 1 && r1[k][0] == seq1[k]),
            decreases seq1.len() - i,
        {
            let mut row: Vec<i8> = Vec::new();
            row.push(seq1[i]);
            r1.push(row);
            i += 1;
        }

        // Build the second 2D list: a single row copy of seq2
        let mut row2: Vec<i8> = Vec::new();
        let mut j: usize = 0;
        while j < seq2.len()
            invariant j <= seq2.len(),
            invariant row2.len() == j,
            invariant forall(|k: usize| k < j ==> row2[k] == seq2[k]),
            decreases seq2.len() - j,
        {
            row2.push(seq2[j]);
            j += 1;
        }
        let mut r2: Vec<Vec<i8>> = Vec::new();
        r2.push(row2);

        (r1, r2)
    }
}

fn main() {
    // example invocation
    let a = vec![1i8, -2, 3];
    let b = vec![-5i8, 0, 7, 8];
    let (out1, out2) = ix_(a, b);
    // now out1 == [[1], [-2], [3]]
    // and out2 == [[-5, 0, 7, 8]]
}